#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Sheet v5: Lisul's one-time setup (docs/sheet-v5.md, "Setup").
#
#   bash tools/sheet-v5-setup.sh
#
# Everything is already deployed. These are the steps only Lisul can take. Every secret goes
# straight into the Supabase dashboard: this script never sees one, and writes no .env. The only
# things it changes itself are the Vault URLs (not secrets) that switch each sync on, and one
# test fire of the morning task. Optional sources can be skipped and done on a later run.

REF=bmbsvvprpfdbvalnkowp
URL="https://$REF.supabase.co"
GCP="project=the-sheet-512218"
SECRETS_PAGE="https://supabase.com/dashboard/project/$REF/functions/secrets"
PLAN="https://lisul-elvi.com/plan/"
cd "$(dirname "$0")/.."

sb() { npx -y supabase@latest "$@"; }

# sql "query" runs one query on the live database and prints only its rows' values.
sql() { sb db query --remote="$REF" --yes "$1" 2>/dev/null | grep -oE '"[a-z_]+": [^,}]+' || true; }

# vault_url NAME FUNCTION adds the Vault URL that switches a sync job on, once.
vault_url() {
  sb db query --remote="$REF" --yes "select vault.create_secret('$URL/functions/v1/$2', '$1')
    where not exists (select 1 from vault.secrets where name = '$1')" >/dev/null 2>&1 \
    && printf '  %s✓ switched on%s %s (Vault %s)\n' "$GREEN" "$RESET" "$2" "$1" \
    || { SKIPPED+=("Vault URL $1 (docs/sheet-v5.md, Deploy step 7)"); warn "couldn't add $1; try again later"; }
}

# What's already set up, read once at the start (names and counts only, never a secret's value),
# so the wizard shows only the steps left. Re-run it any time: finished steps stay hidden.
SECRET_NAMES=""; STATE=""
load_state() {
  # The Supabase CLI must be logged in (to the account that owns the-sheet) for every check and
  # Vault step below; without it the wizard would silently see nothing.
  note "· Supabase login (if this sits here, look for a macOS Keychain prompt and click Always Allow)"
  if ! sb secrets list --project-ref "$REF" >/dev/null 2>&1; then
    warn "The Supabase CLI isn't logged in here (or not to the account that owns the-sheet)."
    say "Run this once, sign in in the browser it opens, then run this wizard again:"
    say "    npx -y supabase@latest login"
    exit 1
  fi
  note "· function secrets (names only)"
  SECRET_NAMES=$(sb secrets list --project-ref "$REF" 2>/dev/null | grep -oE '"name":"[A-Z0-9_]+"' | cut -d'"' -f4 | tr '\n' ' ' || true)
  note "· the database (calendar, Oura, GitHub orgs, replans, habits, sync switches)"
  STATE=$(sql "select
    (select count(*) from calendar_account) as cal,
    (select count(*) from oura_account) as oura,
    (select coalesce(array_length(github_orgs, 1), 0) from settings) as orgs,
    (select replans_on from settings) as replans,
    (select count(*) from habits) as habits,
    (select string_agg(name, ' ') from vault.secrets where name like 'sheet_%_url') as vault")
}
has_secret() { [[ " $SECRET_NAMES " == *" $1 "* ]]; }
in_vault() { [[ "$STATE" == *"$1"* ]]; }
state_is() { grep -qE "\"$1\": *\"?$2" <<<"$STATE"; }
# Which stages still need doing.
need_google() { ! state_is cal '[1-9]'; }
need_calendar() { ! state_is cal '[1-9]' || ! in_vault sheet_busy_url; }
need_oura() { ! state_is oura '[1-9]' || ! in_vault sheet_oura_url; }
need_salt() { ! has_secret SHEET_SENDER_SALT || ! in_vault sheet_mail_url; }
need_github() { ! has_secret SHEET_GITHUB_TOKEN || ! state_is orgs '[1-9]'; }
need_jira() { ! has_secret SHEET_JIRA_TOKEN || ! has_secret SHEET_JIRA_EMAIL || ! has_secret SHEET_JIRA_SITE; }
need_work_url() { { has_secret SHEET_GITHUB_TOKEN || has_secret SHEET_JIRA_TOKEN; } && ! in_vault sheet_work_url; }
need_slack() { ! has_secret SHEET_SLACK_TOKEN || ! in_vault sheet_slack_url; }
need_ical() { ! { has_secret SHEET_HANDSHAKE_ICS || has_secret SHEET_ACADEMIC_ICS; } || ! in_vault sheet_ical_url; }
need_replans() { ! state_is replans true; }
need_settings() { ! state_is habits '[1-9]'; }

run_wizard() {

say "Checking what's already set up…"
load_state
WORK=0

TOTAL_STAGES=0
for g in need_oura need_settings true; do $g && TOTAL_STAGES=$((TOTAL_STAGES + 1)); done

banner "The Sheet v5 setup"

# ── 5b ───────────────────────────────────────────────────────────────────
if need_oura; then
stage "Oura (optional): plan from when you wake"
say "The plan starts 30 minutes after your ring says you woke up, and goes lighter after a rough"
say "night. Only sleep times, readiness and hours slept are kept, 60 days."
if confirm "Set up Oura now?"; then
  open_url "https://cloud.ouraring.com/oauth/applications"
  step "Sign in to Oura, and create a new application (any name, e.g. The Sheet)."
  step "Redirect URI, exactly:"
  say "    $URL/functions/v1/oura-connect/callback"
  step "Scopes: tick daily only. Privacy policy: https://lisul-elvi.com/privacy/"
  step "Save, then keep its Client ID and Client Secret on screen."
  pause "Press Enter when the app is saved"
  open_url "$SECRETS_PAGE"
  step "Add OURA_CLIENT_ID and OURA_CLIENT_SECRET with those values, Save."
  pause "Press Enter when both are saved"
  open_url "$PLAN"
  step "Click ••• → Settings → Oura → Connect, and allow Daily on Oura's screen."
  step "You land back on /plan, and Settings shows Oura connected."
  pause "Press Enter when it says connected"
  oura_connected() { sql "select count(*) as n from oura_account" | grep -qE '"n": *"?[1-9]'; }
  until oura_connected || ! confirm "Not connected yet as far as the database can see. Check again?"; do :; done
  if oura_connected; then
    vault_url sheet_oura_url oura-sync
  else
    SKIPPED+=("Oura not connected yet: re-run this script after Connect")
    warn "Oura isn't connected yet, so its sync stays off. Re-run this script later."
  fi
else
  SKIPPED+=("Oura (optional)")
fi
pause
fi

# ── 13 ───────────────────────────────────────────────────────────────────
if need_settings; then
stage "/plan: your day's settings"
open_url "$PLAN"
step "Click ••• (top right) → Settings, then:"
step "Workload cap: hours of planned work a day (6 by default). Save."
step "Habits: add each one (gym, lunch...) with its days, ideal time, minutes, flex and"
say "    Firm (always placed first) or Flexible."
step "Enrollment: when your SOLAR window opens, if you know it."
step "Triage rules: an address or domain to always or never put in Needs you."
note "All of these can change any time; the next plan uses them."
pause "Press Enter when done"
fi

# ── 14 ───────────────────────────────────────────────────────────────────
if true; then
stage "The live check"
say "Read-only. ✓ is good; ! is a source you haven't connected; ✗ is a problem."
note "Jobs run on their schedule, so a fresh source shows \"no sync yet\" for up to an hour."
pause "Press Enter to run it"
bash tools/verify-sheet-v5.sh 2>&1 | grep -E '^(✗|!)|All checks' || true
pause
fi


finish
}

run_wizard "$@"; exit
